//www.youtube.com/@AjeetBharti", "id": "accc0ef3373c"}]}, {"id": "business", "eyebrow": "Business", "title": "Business", "upsc": false, "items": [{"title": "Jensen Huang pushes Nvidia comeback after board rejects pressure to reinstate ex-boss", "url": "https://www.bbc.co.uk/news/articles/cwx2en2vrxmdo?at_medium=RSS&at_campaign=rss", "summary": "Huang says he has had an \"outpouring\" of calls from investors and others calling for him to return.", "published": "2026-11-17T17:42:26+00:00", "source": "BBC News", "byline": "", "image": "https://ichef.bbci.co.uk/ace/standard/240/cpsprodpb/40ef/live/51fc1a30-e2aa-11f1-99a1-253766e7ad8b.jpg", "licence": "linkout", "id": "b83c0d1555a4", "category": "general", "category_label": "General"}, {"title": "We can't afford to hire under-25s, say firms. Will Milburn plans help?", "url": "https://www.bbc.co.uk/news/articles/c6d01e8m15mko?at_medium=RSS&at_campaign=rss", "summary": "The proposal to cut employers' National Insurance costs is \"essential\" to tackling the Neet problem, one business group says.", "published": "2026-11-17T15:56:04+00:00", "source": "BBC News", "byline": "", "image": "https://ichef.bbci.co.uk/ace/standard/240/cpsprodpb/1236/live/f4363760-e29e-11f1-a094-5fdc692f3e33.png", "licence": "linkout", "id": "48dc1a3164c4", "category": "general", "category_label": "General"}, {"title": "Where are the most jobs for 18-24 year-olds?", "url": "https://www.bbc.co.uk/news/articles/cw3djdjk5d7ko?at_medium=RSS&at_campaign=rss", "summary": "How many jobs are there where you live and in which sectors are you most likely to find an opening?", "published": "2026-11-17T12:35:53+00:00", "source": "BBC News", "byline": "", "image": "https://ichef.bbci.co.uk/ace/standard/240/cpsprodpb/ca90/live/0c02f160-e1ac-11f1-8ee3-23d0d09d2796.jpg", "licence": "linkout", "id": "c6fe273ab62e", "category": "general", "category_label": "General", "figures": ["24 year -olds?"]}, {"title": "Speed camera fault may have allowed drivers to escape fines